/*
 * Split header (DESIGN.md "Split Tabs"): one borderless 78px strip in the list
 * column. Hamburger centered 23px into the pane, tabs on the 50px content
 * inset and vertically centered ~42px down, right glyphs on the 32px action
 * pitch with the last glyph centered 32px from the pane edge. Extra rows
 * (split editor, split error) wrap below the tab line.
 */
.app-header {
  /* The tab column never drops below this: the trail's notes give up width first (DESIGN.md gap 18).
     The floor is what is really in the strip: "Inbox 18" (measured 62px), a saved tab (its label stops at
     12ch, plus the count) and each filter chip ("Unread only" measured 73px), with the 18px gaps between.
     At least 10rem, which covers "Inbox 18" and one chip. */
  --tabs-gap: 18px;
  --tab-inbox: 4.5rem;
  --tab-saved: 9rem;
  --header-chip: 4.75rem;
  --floor-saved: 0px;
  --floor-filter: 0px;
  --header-tabs-floor: max(10rem, calc(var(--tab-inbox) + var(--floor-saved) + var(--floor-filter)));
  display: grid;
  grid-template-columns: 50px minmax(min(var(--header-tabs-floor), 100%), 1fr) minmax(0, auto);
  grid-template-rows: minmax(calc(var(--split-header-height) - 6px), auto);
  align-items: center;
  padding: 6px 16px 0 0;
  background: var(--surface);
}

/* A second tab and each filter chip raise the floor (the tabs never lose their label to the notes). */
.app-header:has(.split-nav > .split-tab + .split-tab) {
  --floor-saved: calc(var(--tabs-gap) + var(--tab-saved));
}

.app-header:has(.header-filter) {
  --floor-filter: calc(var(--tabs-gap) + var(--header-chip));
}

.app-header:has(.header-filter ~ .header-filter) {
  --floor-filter: calc(2 * (var(--tabs-gap) + var(--header-chip)));
}

.app-header > .header-row {
  grid-column: 1 / -1;
  padding-left: 50px;
}

.header-alert {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin: 0 0 6px;
  font-size: var(--type-body);
  color: var(--danger);
}

/* Ghost glyph button: Graphite at rest, Paper White on hover/focus. */
.header-glyph {
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  background: transparent;
